         {'node': sid('checks._rs_validate'), 'title': 'Local preflight', 'state': [['posted', 'yes'], ['TINs', '999999999 / 12345678910: digits, different'], ['currency', 'GEL'], ['date', '2026-09-20: within 5 days ahead and 5 years back'], ['lines', "1 product line, label 'Service' (7 of 255 chars), quantity 2"]], 'note': 'Nothing reaches rs.ge when a check fails; each refusal names the fix.'},
