         {'node': sid('seller._rs_create_invoice'), 'title': 'Create the header', 'state': [['seller_un_id', '731937 (stored on the login by Test SOAP)'], ['buyer_un_id', "1149251: get_un_id_from_tin('12345678910'), cached on the partner"], ['variant', 'regular (no advance, no note)'], ['pending marker', "'create', committed"], ['save_invoice', 'inv_id 0, operation_date 2026-09-20 -> invois_id 700123'], ['stored', "rs_einv_id '700123', rs_einv_status '0', marker cleared, committed"]], 'note': 'The second commit makes the id durable before the line sync; a crash after it leaves a recoverable Draft, not a duplicate.'},
