         {'node': sid('am._rs_stamp_sync_hash'), 'title': 'Fingerprint the synced state', 'state': [['rs_einv_last_sync_hash', 'SHA-256 of header and product lines'], ['rs_einv_has_pending_changes', 'False'], ['line badge', 'Synced']], 'note': 'Any later edit of a line changes the hash and shows Update on RS.'},
