         {'node': sid('seller._rs_cancel_core'), 'title': 'Send the cancellation', 'state': [['refresh', 'get_invoice -> status 2'], ['pending correction', 'none'], ['legacy correction', 'none'], ['status', '2 is in (2, 3, 8)'], ['cancel_invoice', 'change_invoice_status(700123, 6) -> true']], 'note': 'A correction in flight would have to be finished or deleted first: rs.ge cannot hold both.'},
