         {'node': sid('sync._rs_refresh_apply_status'), 'title': 'Apply status 7', 'state': [['rs_einv_status', "'7' (was '6')"], ['rs_einv_cancel_pending_at', 'cleared'], ['condition', 'customer invoice, posted, no reversal: auto-cancel runs']], 'note': '7 is checked on every refresh, not only on the transition, so a cancel that failed once is retried.'},
